            gcd = ideal[i].gcd(ideal[j])
            if gcd != 1:
                ideal.append(gcd)
    return set(ideal)

def compute_resolution_proof_size(poly):
    ring = GF(2)
    variables = list(poly.atoms())
    stack = [poly]
    while stack:
        current = stack.pop()
        if current == 0:
            continue
        for var in variables:
            if current.coeff(var) != 0:
                new_clause = current.coeff(var).as_expr() * ~var + current.as_expr()
